        params.set("Difficulty", SongLuaDifficulty::Medium.sm_name())?;
        return Ok(());
    };
    let meter = call_table_method(&steps, "GetMeter")?;
    params.set(
        "Meter",
        if matches!(meter, Value::Nil) {
            Value::String(lua.create_string("?")?)
        } else {
