            let actor = actor.clone();
            move |_, _args: IgnoredArgs| {
                Ok(actor
                    .get::<Option<f32>>("__songlua_scroller_current_item")?
                    .unwrap_or(0.0))
            }
        })?,
    )?;
    actor.set(
        "SetDestinationItem",
