        "GetNumItems",
        lua.create_function({
            let actor = actor.clone();
            move |_, _args: IgnoredArgs| {
                Ok(actor
                    .get::<Option<i64>>("__songlua_scroller_num_items")?
                    .unwrap_or(1)
                    .max(0))
            }
        })?,
    )?;
    actor.set(
        "SetTransformFromFunction",
        lua.create_function({
            let actor = actor.clone();
            move |_, args: MultiValue| {
                if let Some(Value::Function(function)) = method_arg(&args, 0).cloned() {
