            quad.raw_set("__songlua_parent", actor.clone())?;
            quad.get::<Function>("FullScreen")?.call::<()>(quad.clone())?;
            quad.get::<Function>("diffuse")?.call::<()>((quad.clone(), 0.0, 0.0, 0.0, 0.0))?;
