dofile(GAMESTATE:GetCurrentSong():GetSongDir() .. "easing.lua")
mods = {
    {1, 2, "*100 no invert", "len", 2},
}
mod_time = {
    {0, 5, "*100 no dark", "len"},
}
mods_ease = {
