            ("loop", "circular redirect"),
            ("empty", "empty redirect"),
            ("missing", "not found"),
            ("ambiguous", "multiple matches"),
        ] {
            let error = crate::resolve_load_actor_path(&lua, &song_dir, &format!("parts/{name}"))
                .unwrap_err();
            assert!(error.to_string().contains(expected), "{error}");
        }
    }

