            if GAMESTATE:GetSongBeat() == 0 then
                assert(account.nested.count == 0 and queue_account.count == 0)
            elseif GAMESTATE:GetSongBeat() >= 0.5 then
                assert(account.nested.count == count and queue_account.count == count)
