        let getupvalue = debug.get::<Function>("getupvalue").unwrap();
        let function = lua
            .load(
                r#"
                local target = { name = "target" }
                local duplicate = target
                local ignored = { name = "ignored" }
                return function()
                    return target, duplicate, ignored
                end
                "#,
            )
            .eval::<Function>()
            .unwrap();
        let mut seen = HashSet::new();

