        assert_eq!(out[0].from.x, Some(10.0));
        assert_eq!(out[0].from.y, None);
        assert_eq!(out[0].to.x, Some(30.0));
        assert_eq!(out[0].easing.as_deref(), Some("linear"));
        assert_eq!(out[0].sustain, Some(0.5));
