pub(super) fn text<'a>(call: &'a HostCall<'_>, value: Value) -> Option<&'a str> {
    let Value::String(id) = value else {
        return None;
    };
    std::str::from_utf8(call.string_bytes(id)?).ok()
}

fn alignment(call: &HostCall<'_>, value: Value, vertical: bool) -> Option<f32> {
    if let Some(number) = float_scalar(call, value, false) {
        return Some(number);
    }
    let token = crate::borrowed_alignment_token(text(call, value)?);
    if token.eq_ignore_ascii_case(if vertical { "top" } else { "left" }) {
        Some(0.0)
    } else if token.eq_ignore_ascii_case("center") || token.eq_ignore_ascii_case("middle") {
        Some(0.5)
    } else if token.eq_ignore_ascii_case(if vertical { "bottom" } else { "right" }) {
        Some(1.0)
    } else {
        None
    }
}

pub(super) fn color(call: &mut HostCall<'_>) -> Result<Option<[f32; 4]>, Error> {
    match arg(call, 1) {
        Value::Table(table) => {
            let mut out = [1.0; 4];
            for (i, component) in out.iter_mut().enumerate() {
                let value = call.raw_table_get(table, Value::Number((i + 1) as f64))?;
                if i == 3 && value == Value::Nil {
                    continue;
                }
                // The production table reader uses Lua numeric coercion, which
                // accepts hex strings and nonfinite numbers. It ignores __index.
                let converted = call.call(helper(call, 6)?, &[value])?[0];
                let Value::Number(number) = converted else {
                    return Ok(None);
                };
                *component = number as f32;
            }
            Ok(Some(out))
        }
        Value::String(_) => {
            Ok(text(call, arg(call, 1))
                .map(|text| crate::parse_color_text(text).unwrap_or([1.0; 4])))
        }
        first => {
            let Some(r) = float_scalar(call, first, false) else {
                return Ok(None);
            };
            let Some(g) = float_scalar(call, arg(call, 2), false) else {
                return Ok(None);
            };
            let Some(b) = float_scalar(call, arg(call, 3), false) else {
                return Ok(None);
            };
            Ok(Some([
                r,
                g,
                b,
                float_scalar(call, arg(call, 4), false).unwrap_or(1.0),
            ]))
        }
    }
}

fn push_color(call: &mut HostCall<'_>, color: [f32; 4]) -> Result<(), Error> {
    let table = call.try_new_table()?;
    call.with_roots(&[Value::Table(table)], |call| {
        for (i, component) in color.into_iter().enumerate() {
            call.raw_table_set(
                table,
                Value::Number((i + 1) as f64),
                Value::Number(component as f64),
            )?;
        }
        call.push(Value::Table(table))
    })
}

fn strict_boolean(call: &HostCall<'_>, name: &str) -> Result<bool, Error> {
    match arg(call, 1) {
        Value::Boolean(value) => Ok(value),
        Value::Number(value) => Ok(value.trunc() != 0.0),
        _ => Err(call.error(format!("{name} expects a boolean or number").as_bytes())),
    }
}

fn cull_mode(call: &HostCall<'_>) -> Result<CullMode, Error> {
    match arg(call, 1) {
        Value::Number(0.0) => Ok(CullMode::Back),
        Value::Number(1.0) => Ok(CullMode::Front),
        Value::Number(2.0) => Ok(CullMode::None),
        value => match text(call, value) {
            Some("CullMode_Back") => Ok(CullMode::Back),
            Some("CullMode_Front") => Ok(CullMode::Front),
            Some("CullMode_None") => Ok(CullMode::None),
            Some(value) if value.eq_ignore_ascii_case("back") => Ok(CullMode::Back),
            Some(value) if value.eq_ignore_ascii_case("front") => Ok(CullMode::Front),
            Some(value) if value.eq_ignore_ascii_case("none") => Ok(CullMode::None),
            _ => Err(call.error(b"invalid CullMode")),
        },
    }
}

fn depth(store: &Shared, actor: TableId, test: Option<(bool, bool)>, write: Option<bool>) {
    {
        let mut store = store.lock().unwrap();
        let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
        if let Some((enabled, on_fail)) = test {
            render.depth_test = enabled;
            render.depth_test_on_fail = on_fail;
        }
        if let Some(enabled) = write {
            render.depth_write = enabled;
        }
    }
    for child in children(store, actor) {
        depth(store, child, test, write);
    }
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let value = arg(call, 1);
    // Parse values before taking the metadata lock. Lua numeric conversion and
    // return-table allocation may reenter the VM or collect traced captures.
    if matches!(name, "GetDiffuse" | "GetGlow") {
        let color = {
            let store = store.lock().unwrap();
            let pose = store.actors[&actor].destination();
            if name == "GetDiffuse" {
                pose.diffuse
            } else {
                pose.glow
            }
        };
        return push_color(call, color);
    }
    if name == "getrotation" {
        let rotation = store.lock().unwrap().actors[&actor].state.rotation;
        for value in rotation {
            call.push(Value::Number(value as f64))?;
        }
        return Ok(());
    }
    if name.starts_with("Get") {
        let value = {
            let store = store.lock().unwrap();
            let actor = &store.actors[&actor];
            let render = &actor.state.render;
            match name {
                "GetDiffuseAlpha" => actor.destination().diffuse[3],
                "GetBaseZoomX" => render.basezoom_x,
                "GetBaseZoomY" => render.basezoom_y,
                "GetBaseZoomZ" => render.basezoom_z,
                "GetHAlign" => render.halign,
                "GetVAlign" => render.valign,
                _ => unreachable!(),
            }
        };
        return call.push(Value::Number(value as f64));
    }
    if matches!(name, "diffuse" | "diffusecolor" | "glow" | "shadowcolor")
        || corner_mask(name).is_some()
    {
        if let Some(mut color) = color(call)? {
            let mut store = store.lock().unwrap();
            let sync = !store.playback && matches!(name, "diffuse" | "diffusecolor");
            let actor = store.actors.get_mut(&actor).unwrap();
            if name == "shadowcolor" {
                actor.state.render.shadow_color = color;
            } else {
                let pose = actor.destination_mut();
                if let Some(mask) = corner_mask(name) {
                    for (i, vertex) in pose
                        .vertex_colors
                        .get_or_insert([[1.0; 4]; 4])
                        .iter_mut()
                        .enumerate()
                    {
                        if mask & (1 << i) != 0 {
                            *vertex = color;
                        }
                    }
                } else if name == "glow" {
                    pose.glow = color;
                } else {
                    if name == "diffusecolor" {
                        color[3] = pose.diffuse[3];
                    }
                    pose.diffuse = color;
                }
            }
            if sync {
                actor.sync_rotation_getters();
            }
        }
    } else if matches!(name, "halign" | "valign" | "horizalign" | "vertalign") {
        let align = alignment(call, value, matches!(name, "valign" | "vertalign"));
        let text_align = (name == "horizalign")
            .then(|| text(call, value).and_then(crate::parse_overlay_text_align))
            .flatten();
        let mut store = store.lock().unwrap();
        let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
        if let Some(value) = align {
            if matches!(name, "valign" | "vertalign") {
                render.valign = value;
            } else {
                render.halign = value;
            }
        }
        if let Some(value) = text_align {
            render.text_align = value;
        }
    } else if name == "backfacecull" || name == "cullmode" {
        let mode = if name == "backfacecull" {
            if strict_boolean(call, name)? {
                CullMode::Back
            } else {
                CullMode::None
            }
        } else {
            cull_mode(call)?
        };
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .render
            .cull_mode = mode;
    } else if matches!(name, "zbuffer" | "ztest" | "zwrite") {
        let enabled = strict_boolean(call, name)?;
        depth(
            store,
            actor,
            (name != "zwrite").then_some((enabled, false)),
            (name != "ztest").then_some(enabled),
        );
    } else if name == "ztestmode" {
        let mode = text(call, value).ok_or_else(|| call.error(b"ztestmode expects a ZTestMode"))?;
        let flags = match mode
            .trim()
            .trim_start_matches("ZTestMode_")
            .to_ascii_lowercase()
            .as_str()
        {
            "off" => (false, false),
            "writeonpass" => (true, false),
            "writeonfail" => (true, true),
            _ => return Err(call.error(format!("invalid ZTestMode: {mode}").as_bytes())),
        };
        depth(store, actor, Some(flags), None);
    } else if matches!(name, "SetTextureFiltering" | "SetDrawByZPosition") {
        let enabled = call
            .arguments()
            .get(1)
            .is_none_or(|v| !matches!(v, Value::Nil | Value::Boolean(false)));
        let mut store = store.lock().unwrap();
        let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
        if name == "SetTextureFiltering" {
            render.texture_filtering = enabled;
        } else {
            render.draw_by_z_position = enabled;
        }
    } else if name == "blend" {
        if let Some(blend) = text(call, value).and_then(crate::parse_overlay_blend_mode) {
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .state
                .render
                .blend = blend;
        }
    } else if matches!(
        name,
        "stretchto"
            | "scaletofit"
            | "scaletocover"
            | "zoomto"
            | "zoomtowidth"
            | "zoomtoheight"
            | "vanishpoint"
    ) {
        geometry(call, store, actor, name)?;
    } else if name != "clearzbuffer" {
        let nonfinite = matches!(
            name,
            "croptop"
                | "cropbottom"
                | "fadeleft"
                | "faderight"
                | "fadetop"
                | "fadebottom"
                | "basealpha"
                | "heading"
                | "pitch"
                | "roll"
        ) || (name == "diffusealpha"
            && matches!(value, Value::Number(v) if v.is_infinite()));
        if let Some(number) = float_scalar(call, value, nonfinite) {
            scalar(store, actor, name, number);
        }
    }
    call.push(Value::Table(actor))
}

fn corner_mask(name: &str) -> Option<u8> {
    Some(match name {
        "diffuseupperleft" => 1,
        "diffuseupperright" => 2,
        "diffuselowerleft" => 4,
        "diffuselowerright" => 8,
        "diffuseleftedge" => 5,
        "diffuserightedge" => 10,
        "diffusetopedge" => 3,
        "diffusebottomedge" => 12,
        _ => return None,
    })
}

fn scalar(store: &Shared, actor: TableId, name: &str, value: f32) {
    let mut store = store.lock().unwrap();
    let sync = name == "diffusealpha" && !store.playback;
    let actor = store.actors.get_mut(&actor).unwrap();
    let render = &mut actor.state.render;
    match name {
        "basealpha" => render.base_alpha = value,
        "basezoom" => {
            render.basezoom = value;
            render.basezoom_x = value;
            render.basezoom_y = value;
            render.basezoom_z = value;
        }
        "basezoomx" => render.basezoom_x = value,
        "basezoomy" => render.basezoom_y = value,
        "basezoomz" => render.basezoom_z = value,
        "baserotationx" => render.base_rotation[0] = value,
        "baserotationy" => render.base_rotation[1] = value,
        "baserotationz" => render.base_rotation[2] = value,
        "shadowlength" => render.shadow_len = [value, -value],
        "shadowlengthx" => render.shadow_len[0] = value,
        "shadowlengthy" => render.shadow_len[1] = -value,
        "zbias" => render.z_bias = value,
        "fov" => render.fov = Some(value),
        _ => {
            let pose = actor.destination_mut();
            match name {
                "cropleft" => pose.cropleft = value,
                "cropright" => pose.cropright = value,
                "croptop" => pose.croptop = value,
                "cropbottom" => pose.cropbottom = value,
                "fadeleft" => pose.fadeleft = value,
                "faderight" => pose.faderight = value,
                "fadetop" => pose.fadetop = value,
                "fadebottom" => pose.fadebottom = value,
                "skewx" => pose.skew_x = value,
                "skewy" => pose.skew_y = value,
                "diffusealpha" => pose.diffuse[3] = value,
                "heading" | "pitch" | "roll" => {
                    let axis = match name {
                        "heading" => 1,
                        "pitch" => 0,
                        _ => 2,
                    };
                    pose.quaternion = crate::actor_quaternion::rotate(pose.quaternion, axis, value);
                }
                _ => unreachable!(),
            }
        }
    }
    if sync {
        actor.sync_rotation_getters();
    }
}

fn geometry(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let count = match name {
        "zoomtowidth" | "zoomtoheight" => 1,
        "zoomto" | "vanishpoint" => 2,
        _ => 4,
    };
    let mut values = [0.0; 4];
    for (i, value) in values.iter_mut().enumerate().take(count) {
        match float_scalar(call, arg(call, i + 1), false) {
            Some(number) => *value = number,
            None if name == "stretchto" => {}
            None => return Ok(()),
        }
    }
    if name != "vanishpoint" {
        super::sprites::refresh_size(call, store, actor)?;
    }
    let mut store = store.lock().unwrap();
    let actor = store.actors.get_mut(&actor).unwrap();
    let [width, height] = actor.state.size.map(f32::abs);
    let render = &mut actor.state.render;
    if name == "vanishpoint" {
        render.vanishpoint = Some([values[0], values[1]]);
        return Ok(());
    }
    let align = [render.halign, render.valign];
    let pose = actor.destination_mut();
    match name {
        "zoomtowidth" => pose.zoom_x = values[0] / width,
        "zoomtoheight" => pose.zoom_y = values[0] / height,
        "zoomto" => {
            pose.zoom_x = values[0] / width;
            pose.zoom_y = values[1] / height;
        }
        "stretchto" => {
            let w = values[2] - values[0];
            let h = values[3] - values[1];
            pose.x = values[0] + w / 2.0;
            pose.y = values[1] + h / 2.0;
            pose.zoom_x = w / width;
            pose.zoom_y = h / height;
        }
        "scaletofit" | "scaletocover" => {
            if let Some(plan) =
                crate::scale_to_rect_plan(values, [width, height], align, name == "scaletocover")
            {
                pose.x = plan.pos[0];
                pose.y = plan.pos[1];
                pose.zoom = plan.zoom;
                pose.zoom_x = plan.zoom;
                pose.zoom_y = plan.zoom;
                pose.zoom_z = plan.zoom;
                if plan.flip_x {
                    pose.rot_y_deg = 180.0;
                }
                if plan.flip_y {
                    pose.rot_x_deg = 180.0;
                }
                if plan.flip_x {
                    actor.state.rotation[1] = 180.0;
                }
                if plan.flip_y {
                    actor.state.rotation[0] = 180.0;
                }
            }
        }
        _ => unreachable!(),
    }
    Ok(())
}

//! Opt-in song host integration with the shared Rust Lua engine.
//!
//! This portion owns song clock, RNG, file loading, actor declarations and the
//! Actor/ActorFrame/Quad/Sprite/Sound/ActorMultiVertex/ActorProxy and wrapper instance bindings. Remaining
//! actor methods, managers, baking and live-scene bindings still need migration
//! before this can replace the legacy song compiler.
use crate::{
    LUA_PLAYERS, SONG_LUA_RUNTIME_BEAT_KEY as BEAT, SONG_LUA_RUNTIME_BPS_KEY as BPS,
    SONG_LUA_RUNTIME_DELTA_BEAT_KEY as DELTA_BEAT,
    SONG_LUA_RUNTIME_DELTA_SECONDS_KEY as DELTA_SECONDS, SONG_LUA_RUNTIME_KEY,
    SONG_LUA_RUNTIME_RATE_KEY as RATE, SONG_LUA_RUNTIME_SECONDS_KEY as SECONDS,
    SongLuaCompileContext, song_display_bps, song_elapsed_seconds_at, song_music_rate,
};
use deadlib_lua::{Error, HostCall, Root, TableId, Value, Vm};
mod actors;
mod definitions;
pub use actors::{ActorMesh, ActorScene, ActorSnapshot, FrameTexture};
mod loader;
mod random;
pub use random::RandomSnapshot;
#[cfg(feature = "test-support")]
pub mod test_support;
use std::sync::{
    Arc,
    atomic::{AtomicBool, Ordering},
};

const FREEZE: &str = "__songlua_freeze";
const DELAY: &str = "__songlua_delay";
const BPMS: &str = "__songlua_timing_bpms";
const PLAYERS: &str = crate::runtime::PLAYER_SONG_POSITIONS_KEY;

#[derive(Default)]
struct Clock {
    timing: Option<deadsync_rules::timing::TimingData>,
    no_offset: Option<deadsync_rules::timing::TimingData>,
    live: AtomicBool,
}

#[derive(Clone, Copy)]
enum Operation {
    Float(&'static str),
    Boolean(&'static str),
    MusicSeconds,
    Values(bool),
    SetValues(bool),
    SetBeat,
    Reset,
}

#[derive(Clone)]
struct Binding {
    clock: Arc<Clock>,
    operation: Operation,
}

/// An independent Rust VM with the song clock's Rust host bindings installed.
/// All retained Lua objects are explicit roots or traced callback captures.
/// Separate instances have separate heaps and clock state.
pub struct RustSongRuntime {
    vm: Vm,
    random: random::RandomState,
    loader: Root,
    actor_loader: Root,
    actors: actors::Actors,
    clock: Arc<Clock>,
    runtime: Root,
    position: Root,
    players: Vec<Root>,
    operations: [Root; 6],
}

impl RustSongRuntime {
    pub fn new(context: &SongLuaCompileContext) -> Result<Self, Error> {
        let mut vm = Vm::new();
        let random = random::install(&mut vm, context.random_seed)?;
        let loader = loader::install(&mut vm, &context.song_dir)?;
        let actor_loader = definitions::install(&mut vm)?;
        let clock = Arc::new(Clock {
            timing: context.song_timing.clone(),
            no_offset: context.song_timing.clone().map(|mut timing| {
                timing.set_global_offset_seconds(0.0);
                timing
            }),
            live: AtomicBool::new(context.live),
        });
        let actors = actors::Actors::install(&mut vm, clock.clone())?;
        let runtime = vm.try_new_table()?;
        let runtime_root = vm.pin(Value::Table(runtime))?;
        for key in [BEAT, SECONDS, DELTA_BEAT, DELTA_SECONDS] {
            put(&mut vm, runtime, key, Value::Number(0.0))?;
        }
        put(
            &mut vm,
            runtime,
            BPS,
            number(if context.live {
                10.0
            } else {
                song_display_bps(context)
            }),
        )?;
        put(&mut vm, runtime, RATE, number(song_music_rate(context)))?;
        put(&mut vm, runtime, FREEZE, Value::Boolean(false))?;
        put(&mut vm, runtime, DELAY, Value::Boolean(false))?;
        let tonumber = vm.get_global(b"tonumber")?;
        // Keep the original primitive conversion even if a script replaces it.
        let tonumber_root = vm.pin(tonumber)?;
        let song_position = position(&mut vm, &clock, runtime, tonumber)?;
        let mut players = Vec::new();
        if context.live {
            let positions = vm.try_new_table()?;
            put(&mut vm, runtime, PLAYERS, Value::Table(positions))?;
            for index in 1..=LUA_PLAYERS {
                let player = vm.try_new_table()?;
                vm.raw_table_set(positions, Value::Number(index as f64), Value::Table(player))?;
                for key in [BEAT, SECONDS, BPS, RATE, FREEZE, DELAY] {
                    let key = vm.try_intern(key.as_bytes())?;
                    let value = vm.raw_table_get(runtime, key)?;
                    vm.raw_table_set(player, key, value)?;
                }
                players.push(position(&mut vm, &clock, player, tonumber)?);
            }
        }
        let bpms = vm.try_new_table()?;
        put(&mut vm, runtime, BPMS, Value::Table(bpms))?;
        for (index, &(beat, bpm)) in context.song_timing_bpms.iter().enumerate() {
            let segment = vm.try_new_table()?;
            vm.raw_table_set(
                bpms,
                Value::Number((index + 1) as f64),
                Value::Table(segment),
            )?;
            for (slot, value) in [
                beat,
                bpm,
                song_elapsed_seconds_at(beat, context) * song_music_rate(context),
            ]
            .into_iter()
            .enumerate()
            {
                vm.raw_table_set(segment, Value::Number((slot + 1) as f64), number(value))?;
            }
        }
        let mut roots = Vec::new();
        for operation in [
            Operation::Values(false),
            Operation::Values(true),
            Operation::SetValues(false),
            Operation::SetValues(true),
            Operation::SetBeat,
            Operation::Reset,
        ] {
            let function = vm.new_host_function_with_data(
                callback,
                &[tonumber],
                Binding {
                    clock: clock.clone(),
                    operation,
                },
            )?;
            roots.push(vm.pin(function)?);
        }
        vm.set_global(SONG_LUA_RUNTIME_KEY.as_bytes(), Value::Table(runtime))?;
        vm.unpin(tonumber_root)?;
        Ok(Self {
            vm,
            random,
            loader,
            actor_loader,
            actors,
            clock,
            runtime: runtime_root,
            position: song_position,
            players,
            operations: roots.try_into().expect("six clock operations"),
        })
    }

    /// Register additional song bindings or execute scripts in this same VM.
    /// Values obtained here follow `deadlib-lua`'s ordinary rooting contract.
    pub fn vm_mut(&mut self) -> &mut Vm {
        &mut self.vm
    }

    /// Materialize an actor declaration in this song's VM and run its Init commands.
    /// The migration currently supports Actor, ActorFrame, Quad and Sound instances.
    pub fn instantiate_actor(&mut self, declaration: Value) -> Result<ActorScene, Error> {
        self.actors.instantiate(&mut self.vm, declaration)
    }

    pub fn actor_scene_root(&self, scene: ActorScene) -> Option<Value> {
        self.actors.root(scene)
    }

    pub fn actor_scene_snapshot(&self, scene: ActorScene) -> Option<Vec<ActorSnapshot>> {
        self.actors.snapshot(scene)
    }

    /// Local render states with the retained effect phase and native spin flag.
    /// `frame_clock` is [music seconds, song beat] at the sampling boundary.
    pub fn actor_scene_render_states(
        &self,
        scene: ActorScene,
        frame_clock: [f32; 2],
    ) -> Option<Vec<crate::SongLuaOverlayState>> {
        self.actors.render_states(scene, frame_clock)
    }

    /// Deliver Begin and On to this actor subtree once. Screen activation and
    /// its initial zero-delta update are separate host phases.
    pub fn start_actor_scene(&mut self, scene: ActorScene) -> Result<bool, Error> {
        self.actors.start(&mut self.vm, scene)
    }

    /// Enter retained playback after preparation/startup. This preserves the
    /// production boundary for publishing cached rotation getters on writes.
    pub fn begin_actor_playback(&self) {
        self.actors.begin_playback();
    }

    /// Advance the subtree's existing queues and callbacks in native order.
    pub fn advance_actor_scene(&mut self, scene: ActorScene, delta: f64) -> Result<bool, Error> {
        self.actors.advance(&mut self.vm, scene, delta)
    }

    /// Capture the scene's custom draw callbacks at its current clock and pose.
    /// Run after Update. Live capture replaces the previous ordinary frame,
    /// retaining immediate command submissions until the caller consumes them.
    pub fn draw_actor_scene(&mut self, scene: ActorScene) -> Result<bool, Error> {
        self.actors.draw(&mut self.vm, scene)
    }

    /// Resolve captured actor identities to the compiler/playback source map,
    /// consuming the pending immutable frames. Unmapped references are errors.
    pub fn take_actor_draw_frames(
        &mut self,
        sources: &[(Value, crate::SongLuaDrawSource)],
    ) -> Result<Vec<(usize, crate::SongLuaDrawFrame)>, String> {
        self.actors.take_draw_frames(&mut self.vm, sources)
    }

    /// End an owned screen tree once: detach its top-screen global, deliver End
    /// to descendants of its synthetic root, then stop its sounds. End does not
    /// advance queued work or release Lua instances. An ended tree cannot advance.
    /// Returns false for an already ended, released or foreign scene.
    pub fn end_actor_scene(&mut self, scene: ActorScene) -> Result<bool, Error> {
        self.actors.end(&mut self.vm, scene)
    }

    /// Retire native actors and release their Lua roots. Native scene operations
    /// and renderer reads reject retired actors; retained Lua resource handles
    /// keep their captured values until those handles are collected.
    pub fn release_actor_scene(&mut self, scene: ActorScene) -> Result<bool, Error> {
        self.actors.release(&mut self.vm, scene)
    }

